func (c *CLab) deploy( //nolint: funlen
	ctx context.Context,
	options *DeployOptions,
) ([]clabruntime.GenericContainer, error) {
	if c.LabRuntime != nil {
		return c.deployWithLabRuntime(ctx, options)
	}

	var err error

	err = c.ResolveLinks()
	if err != nil {
		return nil, err
	}

	log.Debugf("lab Conf: %+v", c.Config)

	if options.reconfigure {
		_ = c.destroy(ctx, uint(len(c.Nodes)), true)
		log.Info("Removing directory", "path", c.TopoPaths.TopologyLabDir())

		if err := os.RemoveAll(c.TopoPaths.TopologyLabDir()); err != nil {
			return nil, err
		}
	}

	err = c.prepareLabManagementNetwork(ctx)
	if err != nil {
		return nil, err
	}

	if err := c.checkTopologyDefinition(ctx); err != nil {
		return nil, err
	}

	if err := c.prepareDeployArtifacts(ctx, options.skipLabDirFileACLs); err != nil {
		return nil, err
	}

	// Apply snapshot restore configuration to nodes
	if err := c.configureSnapshotRestore(options); err != nil {
		return nil, err
	}

	nodesWg, execCollection, nodeFailCh, err := c.createNodes(
		ctx,
		options.maxWorkers,
		options.skipPostDeploy,
	)
	if err != nil {
		return nil, err
	}

	if err := waitForNodeDeploy(ctx, nodesWg, nodeFailCh); err != nil {
		return nil, err
	}
	if err := c.syncTailscaleProxy(ctx); err != nil {
		return nil, err
	}
	if err := c.SyncMgmtHostRoutes(ctx); err != nil {
		return nil, err
	}

	// also call deploy on the special nodes endpoints (only host is required for the
	// vxlan stitched endpoints).
	// this must happen after all node workers have finished so that veth pairs created
	// as part of vxlan-stitch links are already deployed before the stitch TC rules are applied.
	eps := c.getSpecialLinkNodes()["host"].GetEndpoints()
	for _, ep := range eps {
		err = ep.Deploy(ctx)
		if err != nil {
			log.Warnf("failed deploying endpoint %s", ep)
		}
	}

	// Stitch links after node workers and host endpoints have finished.
	// The veth pair is already created by node workers and the VxLAN interface is created
	// by host endpoint deploy; Stitch applies the TC redirect rules to bridge them.
	var linkPostDeployWorkers errgroup.Group
	linkPostDeployWorkers.SetLimit(int(options.maxWorkers))
	for _, link := range c.Links {
		linkPostDeployWorkers.Go(func() error {
			if err := link.PostDeploy(ctx); err != nil {
				log.Warnf("failed post-deploying link: %v", err)
			}
			return nil
		})
	}
	_ = linkPostDeployWorkers.Wait()

	execCollection.Log()

	containers, err := c.finalize(ctx, options.exportTemplate, options.graph)
	if err != nil {
		return nil, err
	}

	// set after finalizing, so a failed impairment doesn't skip the lab's exports and state
	if err := clablinks.ApplyLinkImpairments(ctx, linksEndpoints(c.Links)); err != nil {
		return nil, err
	}

	return containers, nil
}

func waitForNodeDeploy(
	ctx context.Context,
	nodesWg *sync.WaitGroup,
	nodeFailCh chan error,
) error {
	if nodesWg != nil {
		nodesWg.Wait()
	}

	close(nodeFailCh)

	// Cancellation takes precedence over errors caused by workers unwinding, and
	// prevents post-deploy work from running against a partial lab.
	if err := ctx.Err(); err != nil {
		return err
	}

	var nodeFailErrs []error
	for nodeErr := range nodeFailCh {
		nodeFailErrs = append(nodeFailErrs, nodeErr)
	}
	if len(nodeFailErrs) > 0 {
		return fmt.Errorf(
			"deployment failed for one or more nodes: %w",
			errors.Join(nodeFailErrs...),
		)
	}

	return nil
}

// prepareLabManagementNetwork creates the management networks that are in use
// and allocates addresses for the nodes attached to them.
func (c *CLab) prepareLabManagementNetwork(
	ctx context.Context,
	existing ...clabtypes.ExistingAddress,
) error {
	if err := c.CreateNetwork(ctx); err != nil {
		return err
	}

	if err := c.allocateLabManagementIPs(ctx, existing); err != nil {
		return err
	}

	return c.setMgmtNetLinkBridges()
}

func (c *CLab) allocateLabManagementIPs(
	ctx context.Context,
	existing []clabtypes.ExistingAddress,
) error {
	preferred := make(map[string]clabtypes.NodeAddresses)
	state, err := c.LoadState()
	if err != nil {
		log.Warn("Ignoring preferred management addresses", "error", err)
	}

	if state != nil {
		for name, addresses := range state.IPAM {
			preferred[name] = addresses
		}
	}

	for _, m := range c.allMgmtNetworks() {
		if c.skipMgmtNetwork(m) {
			continue
		}
		nodes := c.mgmtNetNodes(m)
		if m.IPAM.Provider == clabtypes.IPAMProviderRuntime || len(nodes) == 0 {
			continue
		}

		reserved, err := c.collectReservedManagementAddresses(ctx, m, existing)
		if err != nil {
			return err
		}

		err = mgmt.AllocateManagementIPs(
			ctx,
			m,
			nodes,
			clabtypes.AllocationOptions{
				Existing:  existing,
				Preferred: preferred,
				Reserved:  reserved,
			},
		)
		if err != nil {
			return err
		}
	}

	return nil
}

func (c *CLab) collectReservedManagementAddresses(
	ctx context.Context,
	m *clabtypes.MgmtNet,
	existing []clabtypes.ExistingAddress,
) ([]netip.Addr, error) {
	var subnets []netip.Prefix
	for _, value := range []string{m.IPv4Subnet, m.IPv6Subnet} {
		if value == "" {
			continue
		}
		subnet, err := netip.ParsePrefix(value)
		if err != nil {
			return nil, fmt.Errorf("management subnet %q: %w", value, err)
		}
		subnets = append(subnets, subnet)
	}
	occupied, err := c.globalRuntime().NetworkAddresses(ctx, subnets)
	if err != nil {
		return nil, err

